# Simple pytest example
import pytest

def multiply(a, b):
    return a * b

def test_multiply_positive():
    assert multiply(3, 4) == 12

def test_multiply_negative():
    assert multiply(-2, 3) == -6

def test_multiply_zero():
    assert multiply(5, 0) == 0

# Run with: pytest test_multiply.py -v
